#!/usr/bin/env bash
# Regenerate — or just CHECK — the artifact manifests in this directory.
#
#   ops/manifests/regenerate.sh --check      verify recorded hashes against disk, change nothing
#   ops/manifests/regenerate.sh              recompute the derived fields in place
#   ops/manifests/regenerate.sh --check llm-engine.json     one manifest only
#
# ## Why this file did not exist until now
#
# `llm-chat-model.json` has said *"Generated by ops/manifests/regenerate.sh"* since it was
# committed, and this script has never existed -- 0 commits touch that path and nothing was
# ever deleted from it. The manifest cited a generator that was never written, and
# `gateway-build.json` is written by `ops/deploy/build-gateway.sh` instead. So the convention was
# real and its tooling was half-built, which is how `gateway-build.json` came to describe a
# pre-cutover binary for three days without anything noticing.
#
# ## What it will and will not touch
#
# It recomputes only the fields it can DERIVE from the artifact on disk: size, sha256, ELF
# interpreter, rpath, runpath, and for a tree artifact the per-entry hashes and symlink
# targets. Everything else is preserved byte-for-byte -- the GGUF introspection in the model
# manifest, the rustc/cargo/host_triple in the gateway manifest, every `_comment`, and every
# claim about provenance or reproducibility.
#
# That split is the whole design. A generator that rewrote the descriptive fields would
# happily replace "this artifact is not reproducible from source" with whatever it could
# compute, which is exactly the false claim these manifests exist to prevent. It derives
# facts about bytes and touches nothing about meaning.
#
# ## --check is the important mode
#
# `--check` mutates nothing and exits non-zero when a recorded hash does not match the disk.
# That is what makes a manifest a verification instrument rather than a comment: it can be
# run before a service starts, in a test, or by `ops/deploy/verify-runtime.sh`, and it will refuse
# an artifact that is not the one that was verified.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
[ -f "$ROOT/backend/server.py" ] || { echo "repo root not found at $ROOT" >&2; exit 2; }
DIR="$ROOT/ops/manifests"

MODE=regen
WANT=""
for a in "$@"; do
    case "$a" in
        --check) MODE=check ;;
        --help|-h) sed -n '2,12p' "$0"; exit 0 ;;
        *.json) WANT="$a" ;;
        *) echo "unknown argument: $a" >&2; exit 2 ;;
    esac
done

python3 - "$ROOT" "$DIR" "$MODE" "$WANT" <<'PY'
import hashlib, json, os, pathlib, subprocess, sys

root, mdir, mode, want = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]), sys.argv[3], sys.argv[4]
RED, GRN, OFF = "\033[31m", "\033[32m", "\033[0m"
fails = changed = 0


def sha(p: pathlib.Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def readelf(p, needle):
    try:
        out = subprocess.run(["readelf", "-d", str(p)], capture_output=True, text=True).stdout
    except FileNotFoundError:
        return None
    for line in out.splitlines():
        if needle in line and "[" in line:
            return line.split("[", 1)[1].split("]", 1)[0]
    return "" if "Library" in needle else None


def build_id(p: pathlib.Path):
    """The ELF Build ID note, or None if the file has none.

    This was recorded in every manifest and derived by NOTHING -- three hand-copied hex
    strings that happened to be right. A field that is half-derived is where the next
    staleness starts, so it is derived here now. Verified before the change: all three
    recorded values matched `readelf -n` exactly, so this makes no claim it did not already.
    """
    try:
        out = subprocess.run(["readelf", "-n", str(p)], capture_output=True, text=True).stdout
    except FileNotFoundError:
        return None
    for line in out.splitlines():
        if "Build ID:" in line:
            return line.split("Build ID:", 1)[1].strip()
    return None


def derive_file(p: pathlib.Path) -> dict:
    """Only what the bytes on disk actually say."""
    d = {"size_bytes": p.stat().st_size, "sha256": sha(p)}
    rp, rn = readelf(p, "Library rpath"), readelf(p, "Library runpath")
    if rp is not None:
        d["rpath"] = rp
    if rn is not None:
        d["runpath"] = rn
    bid = build_id(p)
    if bid:
        d["build_id"] = bid
    return d


def derive_tree(p: pathlib.Path) -> list:
    out = []
    for f in sorted(p.iterdir(), key=lambda x: x.name):
        if f.is_symlink():
            out.append({"name": f.name, "type": "symlink", "target": os.readlink(f)})
        else:
            out.append({"name": f.name, "type": "file",
                        "size_bytes": f.stat().st_size, "sha256": sha(f)})
    return out


def report(name, field, got, recorded):
    global fails
    if got == recorded:
        return True
    fails += 1
    print(f"  {RED}MISMATCH{OFF}  {name}  {field}")
    print(f"            recorded {recorded}")
    print(f"            on disk  {got}")
    return False


# A NAMED manifest that does not exist is an error, not a no-op. The glob below would simply
# find nothing and report "0 manifest(s) rewritten", which reads like success -- and
# `ops/deploy/build-gateway.sh` calls this to record a build, so a silent no-op there would leave a
# build with no record while printing OK. This generator also never CREATES a manifest: a
# record that appears with no provenance fields is the false claim the header argues against,
# so an absent one has to be restored deliberately.
if want and not (mdir / want).exists():
    print(f"  {RED}NO SUCH MANIFEST{OFF}  {want}", file=sys.stderr)
    print(f"  {mdir / want} does not exist. This script records artifacts; it does not "
          f"invent manifests.\n  Restore it from git, or write it deliberately.", file=sys.stderr)
    sys.exit(2)

for path in sorted(mdir.glob("*.json")):
    if want and path.name != want:
        continue
    m = json.loads(path.read_text())
    rel = m.get("relative_path")
    if not rel:
        print(f"  {path.name}: no relative_path, skipped")
        continue
    target = root / rel
    if not target.exists():
        fails += 1
        print(f"  {RED}ABSENT{OFF}    {path.name}  {rel} does not exist")
        continue

    if m.get("path_is_directory"):
        tree = derive_tree(target)
        ok = report(path.name, "tree", tree, m.get("tree"))
        for role in ("server", "cli"):
            sub = m.get(role)
            if not sub:
                continue
            sp = root / sub["relative_path"]
            if sp.exists():
                ok &= report(f"{path.name}:{role}", "sha256", sha(sp), sub.get("sha256"))
        new = dict(m)
        new["tree"] = tree
        new["entry_count"] = len(tree)
        new["total_size_bytes"] = sum(e.get("size_bytes", 0) for e in tree)
        for role in ("server", "cli"):
            if role in new:
                sp = root / new[role]["relative_path"]
                if sp.exists():
                    new[role] = {**new[role], **derive_file(sp)}
    else:
        d = derive_file(target)
        ok = all(report(path.name, k, v, m.get(k)) for k, v in d.items() if k in m)
        new = {**m, **{k: v for k, v in d.items() if k in m}}

    # DOES THE MANIFEST NAME THE ARTIFACT THAT IS ACTUALLY DEPLOYED?
    #
    # Hash-consistency is not the same claim. `gateway-build.json` verified cleanly for three
    # days while describing the pre-cutover binary, because that binary was still on disk and
    # its hash still matched. What it did not match was the path the unit launches. So when a
    # manifest names a systemd unit, the unit's ExecStart is checked against it.
    unit = m.get("deployed_by_unit")
    if unit:
        exec_path = ""
        out = subprocess.run(["systemctl", "show", "-p", "ExecStart", unit],
                             capture_output=True, text=True).stdout
        for part in out.replace(";", "\n").split("\n"):
            if "path=" in part:
                exec_path = part.split("path=", 1)[1].strip()
                break
        if exec_path:
            expected = str((root / rel).resolve())
            if exec_path != expected:
                fails += 1
                ok = False
                print(f"  {RED}NOT DEPLOYED{OFF}  {path.name}")
                print(f"            manifest names  {expected}")
                print(f"            {unit} launches {exec_path}")

    if ok:
        print(f"  {GRN}ok{OFF}        {path.name}  {rel}")

    if mode == "regen":
        text = json.dumps(new, indent=2) + "\n"
        if text != path.read_text():
            path.write_text(text)
            changed += 1
            print(f"            rewrote derived fields; descriptive fields preserved")

if mode == "check":
    print()
    print(f"{RED if fails else GRN}{'FAIL' if fails else 'PASS'}{OFF}  "
          f"{fails} manifest mismatch(es)")
    sys.exit(1 if fails else 0)
print(f"\n{changed} manifest(s) rewritten, {fails} mismatch(es) found")
sys.exit(1 if fails else 0)
PY
